import{_ as n,o as s,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const d=JSON.parse('{"title":"Versetzung, Abschlüsse und Abschnittswechsel bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/versetzung.md","filePath":"zeugnisse/versetzung.md"}'),i={name:"zeugnisse/versetzung.md"};function h(u,e,a,l,c,g){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="versetzung-abschlusse-und-abschnittswechsel-bearbeiten" tabindex="-1">Versetzung, Abschlüsse und Abschnittswechsel bearbeiten <a class="header-anchor" href="#versetzung-abschlusse-und-abschnittswechsel-bearbeiten" aria-label="Permalink to &quot;Versetzung, Abschlüsse und Abschnittswechsel bearbeiten&quot;">​</a></h1><p>Schließen Sie Noteneingabe und Zeugnisvorbereitung ab, bevor Sie Versetzungen oder Abschlüsse berechnen. Der spätere Wechsel in einen neuen Lernabschnitt ist ein eigener Arbeitsschritt.</p><p>Prüfen Sie vor Beginn die <a href="/zeugnisse/pruefungsordnungen.html">Zuordnung der Prüfungsordnung nach Schulform und Kohorte</a>. Die neue APO-GOSt gilt erstmals für Schülerinnen und Schüler, die im Schuljahr 2027/28 die EF besuchen.</p><h2 id="versetzung-und-abschluss-vorbereiten" tabindex="-1">Versetzung und Abschluss vorbereiten <a class="header-anchor" href="#versetzung-und-abschluss-vorbereiten" aria-label="Permalink to &quot;Versetzung und Abschluss vorbereiten&quot;">​</a></h2><ol><li>Fehlende Noten und Lehrkräfte unter <a href="/zeugnisse/vorbereitung.html">Zeugnisse vorbereiten</a> prüfen.</li><li>Bei Bedarf <a href="/zeugnisse/vorbereitung/lernbereichsnoten-eingeben-gruppenprozesse-noten-zeugnisvorbereitung.html">Lernbereichsnoten</a> ergänzen.</li><li><a href="/zeugnisse/vorbereitung/versetzungs-abschluss-berechnungen-gruppenprozesse-lernabschnitte-versetzung.html">Versetzung und Abschlüsse gruppenweise berechnen</a> und <a href="/zeugnisse/vorbereitung/ergebnis-versetzungs-abschluss-berechnung-aktuelles-halbjahr-aktueller-abschnitt.html">die Ergebnisse prüfen</a>.</li></ol><p>Die Berechnung unterstützt die Entscheidung; sie ersetzt nicht die Prüfung durch die Schule und die zuständigen Konferenzen. Der Gruppenprozess <a href="/zeugnisse/vorbereitung/abschlussdatum-neu-berechnen-gruppenprozesse-allgemein.html">Das voraussichtliche Abschlussdatum neu berechnen</a> verwendet die Restabschnitte des Jahrgangskatalogs.</p><p>In SchILD-NRW 3.6.0 ist beim Schuljahreswechsel für den <strong>Grundschuljahrgang 04</strong> die Versetzungsart <strong>„Versetzt“</strong> zu verwenden, statt „Abschluss“.</p><h2 id="den-abschnitt-wechseln" tabindex="-1">Den Abschnitt wechseln <a class="header-anchor" href="#den-abschnitt-wechseln" aria-label="Permalink to &quot;Den Abschnitt wechseln&quot;">​</a></h2><p>Für den regulären Halbjahres- oder Schuljahreswechsel verwenden Sie <a href="/einstieg/grundlagen/versetzung-ins-neue-schuljahr-und-abschnittswechsel-durchfuehren-einfuehrung-in-schild-nrw.html">Halbjahres- und Schuljahreswechsel durchführen</a>. <a href="/zeugnisse/vorbereitung/versetzung-uebertrag-ins-neue-halbjahr-oder-abschluss-gruppenprozesse-lernabschnitte-versetzung.html">Schülergruppen getrennt in einen neuen Abschnitt übertragen</a> ist für Gruppen vorgesehen, die getrennt oder zu unterschiedlichen Zeitpunkten übertragen werden müssen.</p><h2 id="einen-abschnitt-korrigieren" tabindex="-1">Einen Abschnitt korrigieren <a class="header-anchor" href="#einen-abschnitt-korrigieren" aria-label="Permalink to &quot;Einen Abschnitt korrigieren&quot;">​</a></h2><p><a href="/zeugnisse/vorbereitung/abschnittsdaten-loeschen-gruppenprozesse-lernabschnitte-versetzung.html">Einen Lernabschnitt mit seinen Leistungsdaten löschen</a> entfernt einen ganzen Abschnitt mit seinen Leistungsdaten. Wird der letzte aktuelle Abschnitt gelöscht, fehlen daraus auch die angezeigten Angaben zu Klasse und Jahrgang. Beachten Sie die im Artikel beschriebenen Folgen und Sicherungshinweise.</p><p>Besondere Verfahren finden Sie bei <a href="/zeugnisse/grundschule.html">Grundschule</a>, <a href="/zeugnisse/zp10.html">ZP10</a>, <a href="/zeugnisse/sekundarstufen.html">Abitur und Fachhochschulreife</a> sowie <a href="/zeugnisse/berufskolleg.html">Berufskolleg</a>.</p>',12)])])}const o=n(i,[["render",h]]);export{d as __pageData,o as default};
